import osimport jsonimport timefrom PySide6.QtCore import Qt, QThread, Signalfrom PySide6.QtWidgets import QWidget, QVBoxLayout, QLabel, QProgressBarfrom PySide6.QtGui import QFont, QColorfrom loguru import loggerfrom infrastructure.brokers.mt5_safe import mt5from infrastructure.data_providers.macro.macro_regime import MacroRegimeEnginefrom infrastructure.security.crypto_vault import decrypt_secretclass InitWorker(QThread):    progress = Signal(int, str)    init_done = Signal()    def run(self):        try:            # Bước 1: Khởi tạo cơ bản            self.progress.emit(10, "[SYSTEM] Loading Core Configurations...")            time.sleep(0.3)            # Bước 2: Thử Auto-Login vào MT5 nếu có config            self.progress.emit(30, "[MT5] Initializing Engine & Auto-Login...")            env_path = os.path.join(                os.path.dirname(os.path.dirname(__file__)), "config", "ai_config.json"            )            if os.path.exists(env_path):                try:                    with open(env_path, "r", encoding="utf-8") as f:                        cfg = json.load(f)                    server = cfg.get("MT5_SERVER")                    acc = cfg.get("MT5_ACCOUNT")                    pwd_raw = cfg.get("MT5_PASSWORD")                    pwd = decrypt_secret(pwd_raw) if pwd_raw else None                    if server and acc and pwd:                        try:                            acc = int(acc)                        except:                            pass                        if not mt5.initialize(login=acc, password=pwd, server=server):                            mt5.initialize()                        mt5.login(acc, password=pwd, server=server)                    else:                        mt5.initialize()                except Exception as e:                    logger.warning(f"Splash Auto-login failed: {e}")                    mt5.initialize()            else:                mt5.initialize()  # Fallback init without credentials            time.sleep(0.5)            # Bước 3: Nạp dữ liệu Vĩ mô & Tin tức            self.progress.emit(60, "[API] Fetching Macro & Economic Calendar...")            engine = MacroRegimeEngine()            # Gọi nhẹ hàm fetch để load cache TradingView & YahooFinance            try:                engine.generate_macro_report()            except Exception as e:                logger.warning(f"Splash pre-fetch Macro failed: {e}")            time.sleep(0.5)            # Bước 4: Hoàn tất            self.progress.emit(100, "[SYSTEM] Ready. Launching Terminal...")            time.sleep(0.2)        except Exception as e:            logger.error(f"Error during splash init: {e}")        finally:            self.init_done.emit()class SplashScreen(QWidget):    def __init__(self):        super().__init__()        # 1. Khung Frameless        self.setWindowFlags(            Qt.WindowType.FramelessWindowHint | Qt.WindowType.WindowStaysOnTopHint        )        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)        self.setFixedSize(500, 300)        # 2. Bố cục chính (Background Xám đen chuyên nghiệp)        self.layout = QVBoxLayout(self)        self.layout.setContentsMargins(0, 0, 0, 0)        self.layout.setSpacing(0)        self.container = QWidget()        self.container.setStyleSheet("""            QWidget {                background-color: #0D1117;                border: 1px solid #30363D;                border-radius: 8px;            }        """)        self.container_layout = QVBoxLayout(self.container)        self.container_layout.setContentsMargins(40, 50, 40, 30)        # 3. Typography        self.lbl_title = QLabel("QUANT AI")        self.lbl_title.setStyleSheet(            "color: #FFFFFF; font-family: 'Segoe UI'; font-size: 32px; font-weight: 800; border: none;"        )        self.lbl_title.setAlignment(Qt.AlignmentFlag.AlignCenter)        self.lbl_subtitle = QLabel("PROFESSIONAL TERMINAL")        self.lbl_subtitle.setStyleSheet(            "color: #58A6FF; font-family: 'Segoe UI'; font-size: 14px; font-weight: 600; letter-spacing: 2px; border: none;"        )        self.lbl_subtitle.setAlignment(Qt.AlignmentFlag.AlignCenter)        self.container_layout.addStretch(1)        self.container_layout.addWidget(self.lbl_title)        self.container_layout.addWidget(self.lbl_subtitle)        self.container_layout.addStretch(1)        # 4. Status & Progress        self.lbl_status = QLabel("Initializing...")        self.lbl_status.setStyleSheet(            "color: #8B949E; font-family: 'Consolas'; font-size: 11px; border: none;"        )        self.lbl_status.setAlignment(Qt.AlignmentFlag.AlignLeft)        self.progress_bar = QProgressBar()        self.progress_bar.setFixedHeight(2)  # Siêu mỏng        self.progress_bar.setTextVisible(False)        self.progress_bar.setStyleSheet("""            QProgressBar {                background-color: #161B22;                border: none;                border-radius: 1px;            }            QProgressBar::chunk {                background-color: #58A6FF;                border-radius: 1px;            }        """)        self.container_layout.addWidget(self.lbl_status)        self.container_layout.addSpacing(8)        self.container_layout.addWidget(self.progress_bar)        self.layout.addWidget(self.container)    def update_progress(self, val, msg):        self.progress_bar.setValue(val)        self.lbl_status.setText(msg)